import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from "react-router-dom";
import { API } from "../utils";
import { FaUserPlus, FaLock } from "react-icons/fa";
import "../styles/main.css";
import 'animate.css';
import dentistImg from "../assets/dentist-banner.jpg"; // pastikan file ini ada

function AddUser() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const saveUser = async (e) => {
    e.preventDefault();
    try {
      await API.post('/register', {
        username,
        password,
      }, {
        headers: {
          'Content-Type': 'application/json'
        }
      });
      navigate("/");
    } catch (error) {
      console.log(error);
    }
  };

  return (
    <div className="columns mt-5 is-centered animate__animated animate__fadeInDown">
      <div className="column is-half">
        <div className="box p-5 custom-box">
          <div className="has-text-centered mb-4">
            <img src={dentistImg} alt="Dentist" className="dentist-img" />
          </div>
          <h1 className="title has-text-centered has-text-info mb-5">
            <FaUserPlus className="mr-2" /> Add New User
          </h1>
          <form onSubmit={saveUser}>
            <div className="field">
              <label className="label">Username</label>
              <div className="control has-icons-left">
                <input
                  type="text"
                  className="input is-medium is-rounded"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="Enter username"
                  required
                />
                <span className="icon is-small is-left">
                  <FaUserPlus />
                </span>
              </div>
            </div>

            <div className="field">
              <label className="label">Password</label>
              <div className="control has-icons-left">
                <input
                  type="password"
                  className="input is-medium is-rounded"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Enter password"
                  required
                />
                <span className="icon is-small is-left">
                  <FaLock />
                </span>
              </div>
            </div>

            <div className="field has-text-centered mt-5">
              <button type="submit" className="button is-info is-medium is-rounded px-5">
                Save User
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

export default AddUser;
